-- ============================================================================
-- PARTIE 35 — Version e-learning du module 2 : séquence 3/3 (Test d'une pratique et retour d'expérience)
-- Source : projet pédagogique Koala Kids (partie 3 : accompagner les enfants dans leurs émotions,
-- tempêtes émotionnelles, posture « boussole », attention portée aux paroles) et séance animée 3/3
-- du module 2 (retour d'expérience en quatre questions, pratique commune sur deux semaines).
-- Séquence en lecture seule d'environ 30 minutes : 28 blocs (9 texte, 7 question, 3 dialogue, 3 reflexion, 1 citation, 1 comparaison, 1 discussion, 1 essayer, 1 retenir, 1 scenes),
-- dont 7 questions avec correction, 3 mises en situation, 3 temps de réflexion et un bloc « Échange ».
-- LA SÉQUENCE RESTE EN BROUILLON (publie = false).
-- Prérequis : partie 33 exécutée (thème e-learning du module 2), parties 25 et 30.
-- À exécuter en 3 temps : 35.1, 35.2, puis 35c.
-- Relançable : la séquence n'est créée qu'une fois, et les blocs ne sont ajoutés que si
-- la séquence n'en contient aucun.
-- Les prénoms (Ilyès, Anaïs, Naël) sont fictifs : ce ne sont pas des enfants du site.
-- ============================================================================

-- ---------------------------------------------------------------------------
-- 35.1 Séquence 3/3 dans le thème e-learning. Attendu : aucune ligne retournée.
-- ---------------------------------------------------------------------------
do $do$
declare tid public.theme.id%type;
begin
  select id into tid from public.theme where nom = $kk$Module 2 – Émotions, pleurs, cadre sans violence (e-learning)$kk$;
  if tid is null then raise notice '35.1 : thème e-learning introuvable, exécuter la partie 33'; return; end if;

  if not exists (select 1 from public.module where theme_id = tid and titre = $kk$Module 2 – 3/3 · Test d'une pratique et retour d'expérience (e-learning)$kk$) then
    insert into public.module(theme_id, titre, accroche, publie, ordre, trame)
    values (tid, $kk$Module 2 – 3/3 · Test d'une pratique et retour d'expérience (e-learning)$kk$,
            $kk$Naël, 2 ans, se jette par terre : il faut ranger les camions. Vous vous accroupissez et vous dites : « Tu es en colère, je comprends. » Il hurle encore. **Est-ce que ça ne marche pas, ou est-ce que ce n'est pas ce qu'on cherche ?**$kk$,
            false, 2, null);
  end if;
end
$do$;
-- FIN 35.1

-- ---------------------------------------------------------------------------
-- 35.2 Blocs de la séquence. Attendu : aucune ligne retournée (blocs ajoutés une seule fois).
-- ---------------------------------------------------------------------------
do $do$
declare mid public.module.id%type;
begin
  select m.id into mid from public.module m join public.theme t on t.id = m.theme_id
  where t.nom = $kk$Module 2 – Émotions, pleurs, cadre sans violence (e-learning)$kk$ and m.titre = $kk$Module 2 – 3/3 · Test d'une pratique et retour d'expérience (e-learning)$kk$;
  if mid is null then raise notice '35.2 : séquence introuvable, exécuter 35.1'; return; end if;
  if exists (select 1 from public.bloc where module_id = mid) then raise notice '35.2 : déjà exécuté'; return; end if;

  insert into public.bloc(module_id, type, contenu, ordre)
  select mid, v.type, v.contenu, v.ordre
  from (values
  ('texte', $kk${"titre": "Ce que vous allez faire", "paragraphes": ["Cette dernière séquence porte sur la posture de la **boussole** : nommer, reconnaître, soutenir. Elle vous aide aussi à **tester une pratique** et à en faire un retour d'expérience. Comptez **25 à 30 minutes**, à votre rythme.", "Vous y trouverez des situations vécues, **sept questions avec correction**, **trois mises en situation** et **trois temps de réflexion**. Les questions ne sont pas notées. Ce que vous écrivez reste sur votre appareil.", "À la fin, vous saurez dire ce qu'a changé une pratique testée pour l'enfant, et choisir avec l'équipe **une pratique commune** pour accompagner les émotions des enfants."]}$kk$::jsonb, 0),
  ('reflexion', $kk${"question": "Dans la séquence précédente, vous avez peut-être repéré une limite que l'équipe n'applique pas de la même façon, ou repris un enfant sans le punir. Qu'avez-vous remarqué ? Si vous n'avez pas eu l'occasion de le faire, notez simplement une situation que vous aimeriez observer.", "sous_titre": "Il ne s'agit pas de vous évaluer. Personne ne lira votre réponse.", "placeholder": "Écrivez ce qui vous vient. Personne ne lira cette réponse."}$kk$::jsonb, 1),
  ('texte', $kk${"titre": "Prêter sa boussole", "paragraphes": ["Un enfant apprend à réguler ses émotions **en fonction de ses relations avec les autres** : il est très influencé par les émotions de ceux qui l'entourent, la joie comme la colère ou la tristesse, et c'est en étant à leur contact et en les imitant qu'il les comprend peu à peu.", "Quand une émotion le submerge, l'adulte se place à ses côtés comme une **boussole** : il **nomme** ce que l'enfant vit, le **reconnaît comme légitime** et lui indique la direction du réconfort. **En lui prêtant sa boussole, l'adulte permet à l'enfant de trouver la sienne.**"]}$kk$::jsonb, 2),
  ('scenes', $kk${"titre": "Trois émotions, trois réponses", "items": [{"lettre": "A", "titre": "Il est fou de joie", "texte": "Ilyès, 2 ans, apprend qu'on part en balade. Il saute, rit, crie de joie. Une adulte lui dit : « Calme-toi, tu fais trop de bruit. »", "analyse": "les émotions positives comptent aussi : elles sont **vraies et dignes d'être exprimées**, elles stimulent les apprentissages. On peut les nommer et les partager : « Tu es très content de partir en balade, tu as raison. »"}, {"lettre": "B", "titre": "Elle pleure en quittant sa maman", "texte": "Anaïs, 18 mois, pleure en voyant sa maman partir. Une adulte lui dit : « Tu n'as aucune raison de pleurer, regarde, tout le monde est content. »", "analyse": "les émotions disent ce que l'enfant vit **ici et maintenant** : elles sont toujours vraies. Les nier ne les fait pas disparaître. On les accepte comme légitimes : « Tu es triste de quitter maman ce matin, je comprends. »"}, {"lettre": "C", "titre": "Il est en colère, on lui propose un choix", "texte": "Naël, 25 mois, est en colère : il faut ranger les camions. Une adulte s'accroupit : « Tu es en colère, je comprends. On range, et tu peux choisir : le panier bleu ou le panier rouge ? »", "analyse": "l'adulte **nomme** la colère, la **reconnaît**, puis propose **un choix possible** pour aider Naël à sortir de sa frustration. Il ne cherche pas à faire cesser l'émotion, ni à détourner l'enfant de ce qu'il ressent."}]}$kk$::jsonb, 3),
  ('question', $kk${"enonce": "Ilyès est fou de joie à l'idée de partir en balade. Quelle réponse accompagne le mieux son émotion ?", "options": [{"texte": "« Calme-toi, tu fais trop de bruit. »", "juste": false}, {"texte": "« Attention, si tu cries, on ne part pas. »", "juste": false}, {"texte": "« Tu es très content de partir en balade, tu as raison. »", "juste": true}], "explication": "Les émotions positives sont aussi **légitimes**. La troisième réponse la **nomme** et la **reconnaît**. Les deux autres cherchent à la **faire cesser**, la dernière avec une menace."}$kk$::jsonb, 4),
  ('texte', $kk${"titre": "Nommer, reconnaître, soutenir", "paragraphes": ["**Nommer.** Mettre des mots sur les émotions de l'enfant lui permet de **comprendre peu à peu ce qu'il vit et ressent**.", "**Reconnaître comme légitime.** Les émotions sont toujours vraies, authentiques et dignes d'être exprimées. Les accepter comme légitimes les rend **acceptables pour l'enfant** (« tu es triste de quitter maman ce matin, je comprends ; tu es très content de partir en balade, tu as raison »). On les prend comme des réactions en lien avec ce qu'il vit, et non comme des exagérations ni des volontés de nuire ou de manipuler.", "**Soutenir.** Il ne s'agit pas de faire cesser l'émotion, mais d'**aller au cœur d'elle avec l'enfant**, en lui parlant de la réalité de ce qu'il est en train de vivre."]}$kk$::jsonb, 5),
  ('question', $kk${"enonce": "Lesquels de ces gestes relèvent de la posture « boussole » ? (plusieurs réponses)", "options": [{"texte": "Nommer l'émotion de l'enfant", "juste": true}, {"texte": "La faire cesser le plus vite possible", "juste": false}, {"texte": "La reconnaître comme légitime", "juste": true}, {"texte": "Proposer, éventuellement, un choix possible pour l'aider à sortir de sa frustration", "juste": true}], "explication": "La boussole **nomme**, **reconnaît** et **soutient**, avec parfois un choix possible. Elle ne cherche pas à **faire cesser** l'émotion : c'est en l'accompagnant que l'enfant apprend peu à peu à l'apprivoiser."}$kk$::jsonb, 6),
  ('texte', $kk${"titre": "Soutenir, pas faire cesser", "paragraphes": ["L'enfant a besoin de **nos mots, de notre empathie et de notre compréhension** pour saisir que ce qu'il vit est légitime, de **notre affection et de notre tendresse** pour consoler sa peine au besoin, et éventuellement d'une **alternative avec un choix possible** pour sortir de sa frustration.", "C'est ainsi que l'enfant apprend peu à peu à **apprivoiser ses émotions**, afin de pouvoir un jour trouver lui-même les solutions pour surmonter les situations et rétablir son bien-être et ses relations avec les autres."]}$kk$::jsonb, 7),
  ('question', $kk${"enonce": "Naël est en colère parce qu'il faut ranger les camions. En plus de reconnaître sa colère, que peut-on lui proposer ?", "options": [{"texte": "Un autre jouet pour qu'il oublie sa colère", "juste": false}, {"texte": "Un choix possible : ranger dans le panier bleu ou dans le panier rouge", "juste": true}, {"texte": "Aucun choix : la règle est la règle", "juste": false}], "explication": "Un **choix possible** aide à sortir de la frustration tout en gardant le cadre : on range, mais l'enfant décide d'un petit quelque chose. Détourner l'attention ne reconnaît pas l'émotion, et refuser tout choix laisse l'enfant dans sa tempête."}$kk$::jsonb, 8),
  ('dialogue', $kk${"label": "Mise en situation", "titre": "« Nommer, ça ne sert à rien »", "contexte": "Réunion d'équipe. Chacun raconte la pratique qu'il a testée. Une collègue prend la parole.", "repliques": [{"qui": "Votre collègue", "texte": "J'ai testé de nommer : « Tu es en colère. » Il a continué à hurler. Ça ne marche pas, je laisse tomber."}], "consigne": "Que lui répondez-vous ?", "reponse_modele": "Merci de l'avoir testé. Nommer ne fait pas cesser l'émotion, et ce n'est pas ce qu'on cherche : on veut que l'enfant se sente compris. Qu'a-t-il fait juste après, précisément ? Il a peut-être crié moins longtemps, ou t'a regardée. Et si c'était difficile, regardons ensemble ce qui t'a gênée avant de décider quoi garder.", "points": ["Remercier : on analyse des pratiques, pas des personnes.", "Rappeler le but : accompagner l'émotion, pas la faire cesser.", "Revenir à ce qui a été observé : qu'a fait l'enfant ensuite, même un peu ?", "Chercher ce qui a été difficile avant de renoncer."]}$kk$::jsonb, 9),
  ('texte', $kk${"titre": "Nommer aussi ce que l'on ressent", "paragraphes": ["Nommer ce que l'on **ressent soi-même** dans la relation à l'enfant l'aide aussi : « Je suis content de te voir ce matin. » L'enfant comprend peu à peu **le sens des différentes émotions**, peut les reconnaître, les nommer et les utiliser à son tour.", "Manifester notre **plaisir et notre intérêt d'être avec eux** favorise leur bien-être, leurs apprentissages, leur estime et leur confiance en eux. Les émotions sont contagieuses : les émotions positives que l'enfant reçoit favorisent, en miroir, ses compétences relationnelles et son empathie."]}$kk$::jsonb, 10),
  ('question', $kk${"enonce": "Pourquoi nommer aussi ce que l'adulte ressent (« je suis content de te voir ce matin ») ?", "options": [{"texte": "Pour que l'enfant comprenne peu à peu le sens des émotions et puisse les reconnaître et les nommer à son tour", "juste": true}, {"texte": "Pour qu'il se sente obligé d'être content lui aussi", "juste": false}, {"texte": "Pour montrer à l'enfant qu'on est de bonne humeur, quoi qu'il arrive", "juste": false}], "explication": "Nommer ses propres émotions donne à l'enfant des **repères** pour comprendre les siennes. Il ne s'agit ni de lui imposer une émotion, ni de cacher ce que l'on ressent."}$kk$::jsonb, 11),
  ('texte', $kk${"titre": "Faire attention à ses paroles", "paragraphes": ["Tout ce que dit et fait l'adulte **s'imprime dans le cerveau de l'enfant**, particulièrement vulnérable à cet âge. Il faut donc être vigilante : **ne pas parler négativement des enfants ni de leurs parents en leur présence**, et ne pas parler de l'enfant entre nous **sans l'inclure dans la conversation**, comme s'il était transparent ou inexistant."]}$kk$::jsonb, 12),
  ('comparaison', $kk${"intro": "**Pour accompagner l'émotion d'un enfant.**", "plutot": ["**Nommer** : « Tu es en colère, tu es triste, tu as eu peur. »", "**Reconnaître** : « Je comprends », « tu as raison ».", "**Consoler** au besoin par les bras, les mots, la tendresse.", "**Proposer un choix possible** pour sortir de la frustration.", "**Nommer ce que je ressens** : « Je suis content de te voir ce matin. »"], "eviter": ["**Nier** : « Tu n'as aucune raison de pleurer. »", "**Minimiser** : « Tu exagères, ce n'est qu'un camion. »", "**Soupçonner** : « Il fait son cinéma pour m'embêter. »", "**Faire cesser à tout prix** : « Arrête de pleurer, calme-toi. »", "**Parler de lui devant lui**, comme s'il n'était pas là."]}$kk$::jsonb, 13),
  ('question', $kk${"enonce": "Lesquelles de ces phrases accompagnent l'émotion sans la nier ni chercher à la faire cesser ? (plusieurs réponses)", "options": [{"texte": "« Tu es en colère parce qu'on range, je comprends. »", "juste": true}, {"texte": "« Tu exagères, ce n'est qu'un camion. »", "juste": false}, {"texte": "« Tu as eu très peur du bruit, je suis là. »", "juste": true}, {"texte": "« Arrête de pleurer, tu fais de la peine à tout le monde. »", "juste": false}], "explication": "Les deux premières phrases justes **nomment** l'émotion et la **reconnaissent**. Les deux autres la **minimisent** ou cherchent à la **faire cesser**, la dernière en culpabilisant l'enfant."}$kk$::jsonb, 14),
  ('dialogue', $kk${"label": "Mise en situation", "titre": "Parler de lui devant lui", "contexte": "12 h 05. À table, deux collègues parlent d'un enfant assis juste à côté d'elles.", "repliques": [{"qui": "Votre collègue", "texte": "Celui-là, il est infernal depuis ce matin. Sa mère n'arrive pas à le tenir non plus."}], "consigne": "Que lui répondez-vous ?", "reponse_modele": "Je vois que la matinée a été dure. Mais il est là, il nous entend, et ça s'imprime en lui. Si tu veux, on en reparle plus tard entre nous, en décrivant ce qui s'est passé plutôt qu'en le jugeant. Et là, on peut lui parler à lui : « Tu as l'air fatigué ce matin. »", "points": ["Reconnaître la difficulté de la collègue.", "Rappeler que l'enfant entend et que ce qu'il entend s'imprime.", "Proposer d'en parler plus tard, en décrivant plutôt qu'en jugeant.", "Inclure l'enfant dans la conversation, avec des mots bienveillants."]}$kk$::jsonb, 15),
  ('reflexion', $kk${"question": "Quel geste de la boussole aimeriez-vous tester pendant une semaine (nommer, reconnaître, proposer un choix, nommer ce que vous ressentez) ? Dans quelle situation précise ?", "sous_titre": "Un seul geste suffit. Personne ne lira votre réponse.", "placeholder": "Écrivez ce qui vous vient. Personne ne lira cette réponse."}$kk$::jsonb, 16),
  ('texte', $kk${"titre": "Tester une pratique, en faire un retour d'expérience", "paragraphes": ["Pour changer une pratique, le plus simple est de **tester un seul geste**, pendant une semaine. Puis on en fait un **retour d'expérience**, en équipe.", "Il se fait en quatre questions. **Qu'ai-je testé, et dans quelle situation ?** **Qu'a fait l'enfant** quand j'ai nommé son émotion ? Qu'est-ce qui a changé, **même un peu ?** **Qu'est-ce qui a été difficile ?** Puis : **que gardons-nous en équipe, que changeons-nous ?**", "On cherche **ce qui s'est passé**, pas qui a bien ou mal fait. Et dans une trace écrite, on n'écrit ni nom d'enfant ni nom de collègue."]}$kk$::jsonb, 17),
  ('question', $kk${"enonce": "Parmi ces phrases d'un retour d'expérience, lesquelles **décrivent** ce qui s'est passé, sans juger ? (plusieurs réponses)", "options": [{"texte": "« J'ai testé de nommer la tristesse d'un enfant à son arrivée : il s'est accroché à moi, puis il a regardé la porte moins longtemps. »", "juste": true}, {"texte": "« Nommer, ça ne marche pas avec les enfants difficiles. »", "juste": false}, {"texte": "« Quand j'ai dit « tu es en colère », il a cessé de taper et m'a regardée. »", "juste": true}, {"texte": "« J'ai mal fait, je n'ai pas su trouver les mots. »", "juste": false}], "explication": "Un bon retour d'expérience **décrit** ce qu'on a testé et ce qu'on a vu. Les autres phrases **étiquettent** des enfants (« difficiles ») ou **jugent** la personne (« j'ai mal fait »), ce qui bloque l'échange."}$kk$::jsonb, 18),
  ('dialogue', $kk${"label": "Mise en situation", "titre": "« Quand un enfant crie, je m'énerve »", "contexte": "Réunion d'équipe. Une collègue prend la parole à voix basse.", "repliques": [{"qui": "Votre collègue", "texte": "Moi, quand un enfant crie longtemps, je ne sais plus quoi dire et je finis par m'énerver. Je n'ose pas en parler en réunion."}], "consigne": "Que lui répondez-vous ?", "reponse_modele": "Merci de le dire, ce n'est pas facile. Ça arrive à beaucoup d'entre nous : dire qu'on n'en peut plus, c'est ce qui évite que ça déborde sur l'enfant. Si tu veux, je prends le relais quand tu sens que ça monte, et on le met à l'ordre du jour pour que l'équipe en parle ensemble.", "points": ["Remercier : parler de ses propres émotions est indispensable.", "Dédramatiser : on peut être débordée, sans jugement.", "Proposer un relais concret.", "Reporter la situation à l'équipe : analyser les difficultés ensemble."]}$kk$::jsonb, 19),
  ('texte', $kk${"titre": "Choisir une pratique commune", "paragraphes": ["À la fin d'un cycle de tests, l'équipe choisit **une pratique commune**, à tenir pendant **deux semaines**. Elle se décrit en **une phrase**, que chacun peut expliquer de la même façon : par exemple « quand un enfant est submergé par une émotion, la personne la plus proche s'accroupit, nomme ce qu'il vit et reste avec lui, sans chercher à la faire cesser ».", "Ensuite, chacun s'engage sur **un geste précis**, noté sur sa fiche de trace. C'est ce qui transforme une bonne idée en pratique."]}$kk$::jsonb, 20),
  ('question', $kk${"enonce": "Laquelle de ces formulations décrit une pratique commune utilisable ?", "options": [{"texte": "« Être bienveillants avec les enfants. »", "juste": false}, {"texte": "« Chacun nomme les émotions comme il le sent, quand il le peut. »", "juste": false}, {"texte": "« Quand un enfant est submergé, la personne la plus proche s'accroupit, nomme l'émotion et reste avec lui. »", "juste": true}], "explication": "Une pratique commune se décrit **en une phrase**, avec un **geste précis** que chacun peut expliquer de la même façon. « Être bienveillants » est trop vague, et « chacun comme il le sent » n'est pas commun."}$kk$::jsonb, 21),
  ('reflexion', $kk${"question": "Quelle pratique commune pourrait choisir votre équipe pour accompagner les émotions des enfants ? Écrivez-la en une phrase, et le geste précis auquel vous vous engagez.", "sous_titre": "Une phrase suffit. Personne ne lira votre réponse.", "placeholder": "Écrivez ce qui vous vient. Personne ne lira cette réponse."}$kk$::jsonb, 22),
  ('retenir', $kk${"titre": "À retenir", "points": ["**Nommer :** « Tu es triste de quitter maman ce matin. » L'enfant apprend peu à peu ce qu'il vit.", "**Reconnaître comme légitime :** une émotion est toujours vraie, ni une exagération ni une manipulation. Les émotions positives comptent aussi.", "**Soutenir, pas faire cesser :** nos mots, notre empathie, notre tendresse, et parfois un choix possible pour sortir de la frustration.", "**Nommer aussi ce que je ressens :** « Je suis content de te voir ce matin. »", "**Faire attention à ses paroles :** ni négatives sur les enfants ou les parents devant eux, ni parler de l'enfant comme s'il n'était pas là.", "**Tester, raconter, choisir :** un retour d'expérience décrit ce qui s'est passé et aboutit à une pratique commune en une phrase."]}$kk$::jsonb, 23),
  ('essayer', $kk${"label": "À essayer après la séquence", "titre": "Une pratique commune pour les émotions", "etapes": [{"titre": "La décrire en une phrase.", "texte": "Un geste simple, que chacun peut expliquer de la même façon."}, {"titre": "La tenir deux semaines.", "texte": "Sans chercher la perfection : on note ce qui marche et ce qui coince."}, {"titre": "En reparler en équipe.", "texte": "À la prochaine réunion, quelques minutes pour dire ce qu'on garde et ce qu'on change."}], "note": "Toute pratique commune se décrit en une phrase."}$kk$::jsonb, 24),
  ('discussion', $kk${"label": "Échange avec les autres participants", "titre": "Partagez une pratique commune", "consigne": "Quelle pratique commune votre équipe pourrait-elle choisir pour accompagner les émotions des enfants ? Formulez-la en une phrase, sans nom d'enfant ni de collègue, puis lisez ce que proposent les autres participants."}$kk$::jsonb, 25),
  ('citation', $kk${"texte": "« L'enfant ne devient pas un Homme, il en est déjà un. »\nJanusz Korczak, Le droit de l'enfant au respect"}$kk$::jsonb, 26),
  ('texte', $kk${"titre": "Pour aller plus loin", "paragraphes": ["Vous avez terminé le **module 2 : émotions, pleurs, cadre sans violence**. Pour approfondir, la source citée dans le projet pédagogique : **Janusz Korczak**, « Le droit de l'enfant au respect » (1929, éditions Fabert, 2017), et « Quand je redeviendrai petit ».", "Dans le prochain module du programme, vous verrez **les soins, le sommeil et l'alimentation**."]}$kk$::jsonb, 27)
  ) as v(type, contenu, ordre);

  raise notice '35.2 : 28 blocs ajoutés';
end
$do$;
-- FIN 35.2

-- ---------------------------------------------------------------------------
-- 35c Contrôle (lecture seule). Attendu : 3 lignes (séquences 1/3, 2/3 et 3/3) ; la 3/3 avec 28 blocs (9 texte, 7 question, 3 dialogue, 3 reflexion, 1 citation, 1 comparaison, 1 discussion, 1 essayer, 1 retenir, 1 scenes),
-- publie = false, sans trame.
-- ---------------------------------------------------------------------------
select m.titre, m.publie, (m.trame is null) as sans_trame, m.ordre,
       (select count(*) from public.bloc b where b.module_id = m.id) as blocs,
       (select string_agg(x.type || ' ' || x.n, ', ' order by x.type)
          from (select b.type, count(*) as n from public.bloc b where b.module_id = m.id group by b.type) x) as repartition
from public.module m join public.theme t on t.id = m.theme_id
where t.nom = $kk$Module 2 – Émotions, pleurs, cadre sans violence (e-learning)$kk$ order by m.ordre;
-- FIN 35c
